+async function checarTodos(db, agoraIso, deps = {}) {
+  const emPregao = require('./cotacoes').emPregao;
+  if (!emPregao(new Date(agoraIso))) {
+    return { pulou: 'fora do pregão' };
+  }
+  const enviarEmail = require('./alertas').enviarEmail;
+  const usuarios = await db.collection('prumo_users').get();
+  let pessoas = 0;
+  let disparos = 0;
+  let enviados = 0;
+  let falhas = 0;
+  for (const u of usuarios.docs) {
+    const base = db.collection('prumo_users').doc(u.id);
+    const snapRobos = await base.collection('robos').get();
+    if (!snapRobos.docs || snapRobos.docs.length === 0) continue;
+    pessoas++;
+    let dispPessoa = [];
+    try {
+      const res = await checarPessoa(base, deps, agoraIso);
+      dispPessoa = res.disparos;
+    } catch { falhas++; continue; }
+    disparos += dispPessoa.length;
+    if (!dispPessoa.length) continue;
+    let cfg;
+    try {
+      const snap = await base.collection('config').doc('alertas').get();
+      cfg = snap && snap.exists ? snap.data() : null;
+    } catch { cfg = null; }
+    const podeEmail = cfg && cfg.canais && cfg.canais.email === true && cfg.email_para;
+    if (!podeEmail) continue;
+    try {
+      const assunto = `Kernex Finance: ${dispPessoa.length} robô(s) dispararam`;
+      const texto = dispPessoa.map((d) => '• ' + d.texto).join('\n') + '\n\nQuem compra ou vende é você. Você controla os robôs no app, aba Robôs.';
+      const e = await enviarEmail(deps, { to: cfg.email_para, assunto, texto });
+      if (e.ok) enviados++; else { falhas++; }
+    } catch { falhas++; }
+  }
+  return { pessoas, disparos, enviados, falhas };
